<?php
function ui_e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function ui_money(mixed $c): string { $c=(int)$c; return 'R '.number_format(intdiv($c,100),0,'.',' ').'.'.str_pad((string)($c%100),2,'0',STR_PAD_LEFT); }
function ui_category(string $s): string { return ['laptops'=>'Laptops','desktops'=>'Desktop PCs','pcs'=>'Desktop PCs','components'=>'Components','accessories'=>'Accessories','surveillance'=>'Surveillance','networking'=>'Networking','pos'=>'POS systems'][$s]??ucwords(str_replace('-',' ',$s)); }
function ui_icon(string $name, string $class=''): string {
 $icons=['arrow'=>'M5 12h14m-6-6 6 6-6 6','search'=>'m21 21-5-5M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16','cart'=>'M3 3h2l3 12h10l3-9H6M9 20h.01M18 20h.01','heart'=>'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z','user'=>'M20 21v-2a7 7 0 0 0-14 0v2M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8','compare'=>'M6 3v18M18 3v18M3 7h6m6 10h6','plus'=>'M12 5v14M5 12h14','minus'=>'M5 12h14','close'=>'m6 6 12 12M6 18 18 6','chevron'=>'m6 9 6 6 6-6','chip'=>'M7 7h10v10H7zM9 2v5m6-5v5M9 17v5m6-5v5M2 9h5m-5 6h5m10-6h5m-5 6h5','check'=>'m5 12 4 4L19 6','shield'=>'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z','box'=>'m12 3 9 5-9 5-9-5 9-5Zm-9 5v9l9 5 9-5V8M12 13v9','headphones'=>'M3 14v-3a9 9 0 0 1 18 0v3M3 13h4v8H3zm14 0h4v8h-4z','menu'=>'M3 6h18M3 12h18M3 18h18','grid'=>'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z','list'=>'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01','mail'=>'M3 5h18v14H3zM3 5l9 8 9-8','download'=>'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5','share'=>'M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm12 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM9 10l6-4M9 14l6 4','bolt'=>'m13 2-9 12h7l-1 8 10-13h-7l1-7Z','filter'=>'M4 7h16M7 12h10M10 17h4','chat'=>'M21 11a9 9 0 0 1-9 9H4l-3 2 2-6a9 9 0 1 1 18-5Z','external'=>'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7'];
 return '<svg class="icon '.ui_e($class).'" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'.($icons[$name]??$icons['box']).'"/></svg>';
}
function ui_form_start(string $endpoint, string $class='', string $redirect=''): void {global $session;echo '<form class="api-form '.ui_e($class).'" data-endpoint="'.ui_e($endpoint).'"'.($redirect?' data-redirect="'.ui_e($redirect).'"':'').' method="post"><input type="hidden" name="_csrf" value="'.ui_e($session['csrf']??'').'"><div class="form-message" role="status" hidden></div>';}
function ui_input(string $name,string $label,string $type='text',bool $required=true,string $value=''): void{echo '<label class="field"><span>'.ui_e($label).'</span><input name="'.ui_e($name).'" type="'.ui_e($type).'" '.($required?'required ':'').'value="'.ui_e($value).'"'.($type==='password'?' minlength="12"':'').'></label>';}
function ui_card(array $p): void {global $demo;
 $url='/products/'.rawurlencode($p['slug']);$specs=array_slice($p['specs']??[],0,3);$stock=(int)($p['stock']??0);
 echo '<article class="product-card" data-product-id="'.(int)$p['id'].'"><div class="product-visual"><a href="'.ui_e($url).'" tabindex="-1" aria-hidden="true"><img src="'.ui_e($p['image']??'').'" alt="" loading="lazy" width="400" height="320"></a><button class="icon-button save-button" data-wishlist="'.(int)$p['id'].'" aria-label="Save '.ui_e($p['name']).'">'.ui_icon('heart').'</button><button class="quick-view" data-quickview="'.ui_e($p['slug']).'">Quick view</button></div><div class="product-body"><p class="brand-label">'.ui_e($p['brand']??'').'</p><h3><a href="'.ui_e($url).'">'.ui_e($p['name']).'</a></h3><p class="card-specs">'.ui_e(implode(' · ',array_map(fn($s)=>is_scalar($s)?(string)$s:'',array_values($specs)))).'</p><div class="stock-label '.($stock>0?'available':'unavailable').'"><i></i>'.($demo?($stock>0?'Demo stock available':'Unavailable in preview'):($stock>0?'Available':'Check availability')).'</div><div class="card-bottom"><div class="price"><strong>'.ui_money($p['price_cents']??0).'</strong>'.(!empty($p['old_price_cents'])&&$p['old_price_cents']>$p['price_cents']?'<s>'.ui_money($p['old_price_cents']).'</s>':'').'</div><button class="add-button" data-add="'.(int)$p['variant_id'].'" aria-label="Add '.ui_e($p['name']).' to basket" '.($stock<1?'disabled':'').'>'.ui_icon('cart').'<span>Add to basket</span></button></div><button class="compare-button" data-compare="'.(int)$p['id'].'" data-slug="'.ui_e($p['slug']).'">'.ui_icon('compare').' Compare</button></div></article>';
}
function ui_breadcrumb(string $label): void {echo '<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><span>'.ui_e($label).'</span></nav>';}
function ui_empty(string $title,string $copy,string $href='/catalog',string $cta='Explore the collection'): void {echo '<div class="empty-state">'.ui_icon('box').'<h2>'.ui_e($title).'</h2><p>'.ui_e($copy).'</p><a class="button primary" href="'.ui_e($href).'">'.ui_e($cta).' '.ui_icon('arrow').'</a></div>';}
